const mkDb = (ms = 100) => { const db = { inFlight: 0, peak: 0 };
  db.query = (id) => { db.inFlight++; db.peak = Math.max(db.peak, db.inFlight);
    return new Promise((ok) => setTimeout(() => { db.inFlight--; ok('note ' + id); }, ms)); };
  return db; };
const db = mkDb();

